'use strict';
let language;
try { language = localStorage.getItem('tj-language') === 'ko' ? 'ko' : 'en'; } catch { language = 'en'; }
let activeProject = null, activeNode = 0, previousProjectId;
let activeView='home';
const workHref='#work';
const tr = value => typeof value === 'object' && value !== null && 'en' in value ? value[language] : value;
const esc = text => String(text ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const say = (en,ko) => esc(language === 'en' ? en : ko);
const txt = value => esc(tr(value));
const arrow = '<span class="arrow" aria-hidden="true">↗</span>';
const main = document.getElementById('main');
const assetBase = new URL('assets/', document.currentScript.src);
const resumeUrl = new URL('Taekjun_Lee_Resume_20261026.pdf', assetBase).href;
const resumePdfUrl = resumeUrl;
function renderChrome(project=null){
 document.documentElement.lang=language;
 const items=[['#home','01','Overview','소개'],['#work','02','Projects','프로젝트'],['#journey','03','My journey','성장 여정'],['#philosophy','04','AI philosophy','AI 개발 철학'],['#about','05','Experience','경력'],['#contact','06','Contact','연락처']];
 const navItems=items.map(([href,num,en,ko])=>`<a href="${href}" data-main-nav><span class="nav-number" aria-hidden="true">${num}</span><span>${say(en,ko)}</span></a>`).join('');
 document.getElementById('header').innerHTML=`<nav class="nav container" aria-label="${say('Main navigation','주요 메뉴')}"><a class="brand" href="#home" aria-label="${say('TJ Lee, home','TJ Lee, 홈')}"><span class="monogram">tj<i>.</i></span><span class="brand-name">TAEKJUN LEE<small>SYSTEMS & AUTOMATION</small></span></a><p class="rail-caption">${say('PORTFOLIO / SELECTED WORK','포트폴리오 / 주요 경험')}</p><div class="nav-controls"><div class="desktop-navigation">${navItems}</div><details class="mobile-navigation"><summary>${say('Explore','둘러보기')} <span aria-hidden="true">☰</span></summary><div class="mobile-nav-panel">${navItems}<a href="${esc(resumePdfUrl)}" target="_blank" rel="noopener">${say('Résumé (PDF)','이력서 (PDF)')} ${arrow}</a></div></details><div class="rail-projects" ${project?'':'hidden'}><span class="eyebrow">${say('CASE STUDIES','프로젝트 사례')}</span>${projects.map(c=>`<a href="#project/${c.id}" ${project?.id===c.id?'aria-current="page"':''}><span>${c.number}</span>${txt(c.navLabel)}</a>`).join('')}</div><div class="rail-bottom"><a class="rail-resume" href="${esc(resumePdfUrl)}" target="_blank" rel="noopener">${say('Résumé (PDF)','이력서 (PDF)')} ${arrow}</a><button class="language" aria-label="${say('Switch to Korean','영어로 전환')}">${language==='en'?'EN / <span class="muted">KO</span>':'<span class="muted">EN</span> / KO'}</button><a class="rail-email" href="mailto:${profile.email}">${profile.email}</a></div></div></nav>`;
 document.getElementById('footer').innerHTML=`<div class="container footer-inner"><span>© ${new Date().getFullYear()} Taekjun (TJ) Lee · ${say('Built with purpose.','목적이 분명한 시스템을 만듭니다.')}</span><a href="#home">${project?say('Back to overview','전체 소개로'):say('Back to top','처음으로')} ↑</a></div>`;
 document.querySelector('.language').addEventListener('click',switchLanguage);
}
function switchLanguage(){
 const savedScroll=window.scrollY,savedNode=activeNode,openNotes=Array.from(document.querySelectorAll('.technical-note')).map(n=>n.open);
 language=language==='en'?'ko':'en';try{localStorage.setItem('tj-language',language);}catch{}
 render(true);
 if(activeProject){selectNode(savedNode);document.querySelectorAll('.technical-note').forEach((note,index)=>note.open=!!openNotes[index]);}
 if(activeView==='journey'&&location.hash.startsWith('#journey/'))scrollJourneyStage();else window.scrollTo({top:savedScroll,behavior:'instant'});
 document.querySelector('.language').focus({preventScroll:true});
}
function heroArt(){return `<svg viewBox="0 0 500 470" role="img" aria-label="${say('From field operations through shared data to connected applications','현장 업무에서 공통 데이터를 거쳐 연결된 애플리케이션으로')}"><defs><pattern id="hero-dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#b4bed0"/></pattern><marker id="ha" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#8394b1"/></marker></defs><rect x="4" y="25" width="492" height="408" rx="20" fill="url(#hero-dots)"/><g fill="none" stroke="#a3b0c5" stroke-width="1.3" marker-end="url(#ha)"><path d="M140 142H218V193"/><path d="M250 242V285H353V317"/><path d="M282 210H400V165"/><path d="M95 183V350H281"/></g><path d="M250 242V285H353V317" class="flow-edge active"/><g transform="translate(36 85)"><rect width="145" height="99" rx="10" fill="#fff" stroke="#bbc5d5"/><g transform="translate(16 17)" stroke="#52637f" fill="none" stroke-width="1.5"><path d="M0 20V7l13 7V7l13 7V0h8v20H0z"/><path d="M5 16v4m8-4v4m8-4v4"/></g><text x="16" y="62" font-size="13" fill="#14233b" font-family="Arial">${say('Field operations','현장 업무')}</text><text x="16" y="81" font-size="9" fill="#5f7395" font-family="monospace">DOMAIN KNOWLEDGE</text></g><g transform="translate(180 192)"><rect width="145" height="98" rx="10" fill="#dbeafe" stroke="#7689a8"/><g transform="translate(16 15)" stroke="#2c446e" fill="none" stroke-width="1.5"><ellipse cx="13" cy="4" rx="13" ry="4"/><path d="M0 4v18c0 6 26 6 26 0V4M0 12c0 6 26 6 26 0"/></g><text x="16" y="62" font-size="13" fill="#14233b" font-family="Arial">${say('Reliable data','신뢰할 수 있는 데이터')}</text><text x="16" y="81" font-size="9" fill="#4a5973" font-family="monospace">SHARED FOUNDATION</text></g><g transform="translate(335 70)"><rect width="143" height="95" rx="10" fill="#fff" stroke="#bbc5d5"/><g transform="translate(16 16)" stroke="#52637f" fill="none" stroke-width="1.5"><rect width="29" height="22" rx="3"/><path d="M0 6h29M7 12h5m4 0h5M7 17h13"/></g><text x="16" y="60" font-size="13" fill="#14233b" font-family="Arial">${say('Connected systems','연결된 시스템')}</text><text x="16" y="79" font-size="9" fill="#5f7395" font-family="monospace">WEB + INTEGRATIONS</text></g><g transform="translate(280 318)"><rect width="185" height="86" rx="10" fill="#14233b"/><circle cx="23" cy="24" r="5" fill="#dbeafe"/><text x="38" y="28" font-size="10" fill="#b8c2d2" font-family="monospace">${say('LESS MANUAL WORK','반복 업무 감소')}</text><text x="18" y="60" font-size="16" fill="#fff" font-family="Arial">${say('Better ways to work.','더 나은 업무 방식.')}</text></g><circle cx="400" cy="210" r="4" fill="#2563eb"/><text x="38" y="244" font-size="9" fill="#5f7395" font-family="monospace">UNDERSTAND.</text><text x="38" y="261" font-size="9" fill="#5f7395" font-family="monospace">CONNECT.</text><text x="38" y="278" font-size="9" fill="#5f7395" font-family="monospace">AUTOMATE.</text></svg>`;}
function workOverview(){return `<div class="selected-grid">${projects.slice(0,3).map(card).join('')}</div>`;}
function journeyTeaser(){
 const stages=[['field-engineering','Facilities engineer','설비 엔지니어','Understand equipment, people and operational constraints.','설비·사용자·현장의 제약을 이해했습니다.'],['master-data','Data & systems analyst','데이터 · 시스템 분석가','Turn operational needs into shared data and connected workflows.','현장 요구를 데이터 표준과 연결된 업무로 설계했습니다.'],['delivery','Developer & business automation','개발자 · 비즈니스 자동화','Build, deploy and operate the software that changes the workflow.','업무를 바꾸는 소프트웨어를 개발·배포·운영합니다.']];
 return `<section class="journey-section journey-teaser" id="journey-preview"><div class="container"><div class="journey-teaser-head"><div><div class="eyebrow">02 / ${say('HOW MY RESPONSIBILITIES GREW','담당 범위가 넓어진 과정')}</div><h2>${say('Understand the work.','업무를 이해하고,')}<br>${say('Then change how it works.','일하는 방식을 바꿉니다.')}</h2></div><div><p class="journey-intro">${say('My work grew from equipment operations into data integration, software development and business automation.','설비 운영에서 데이터·시스템 분석으로, 다시 소프트웨어 개발과 업무 자동화로 역할을 넓혔습니다.')}</p><a class="journey-link" href="#journey">${say('Follow the connected journey','과제와 성장의 연결 보기')} ${arrow}</a></div></div><div class="growth-path">${stages.map(([id,en,ko,descEn,descKo],i)=>`<a href="#journey/${id}"><span class="eyebrow">0${i+1}</span><strong>${say(en,ko)}</strong><span>${say(descEn,descKo)}</span>${arrow}</a>`).join('')}</div></div></section>`;
}
function renderJourney(){
 activeProject=null;activeView='journey';document.body.classList.remove('project-page');document.title=language==='en'?'My engineering journey — TJ Lee':'성장 여정 — TJ Lee';
 main.innerHTML=`<article class="journey-page page-enter"><div class="container"><div class="case-topbar"><a class="back-link" href="${workHref}">← ${say('Explore selected work','프로젝트 살펴보기')}</a><span class="eyebrow">${say('FIELD → DATA → SOFTWARE → AUTOMATION','현장 → 데이터 → 소프트웨어 → 자동화')}</span></div><section class="journey-hero"><div class="eyebrow orange">${say('ONE CONNECTED ENGINEERING JOURNEY','하나로 이어지는 엔지니어링 여정')}</div><h1>${say('From the field','현장의 문제에서')}<br>${say('to connected systems.','연결된 시스템까지.')}</h1><p>${say('I began by maintaining equipment and investigating operational data. My responsibilities expanded into data and process design, then the development, deployment and operation of connected applications.','설비를 유지보수하고 운영 데이터를 분석하는 일에서 시작했습니다. 이후 데이터·업무 설계, 연결된 애플리케이션의 개발·배포·운영으로 담당 범위를 넓혀왔습니다.')}</p></section><div class="journey-reading-note"><strong>${say('Reading note','읽기 안내')}</strong><p>${say('Projects follow how the work evolved; some ran in parallel. Each case shows its dates.','역할과 과제의 발전 순서이며, 일부 프로젝트는 병행했습니다. 수행 기간은 각 사례에 표시했습니다.')}</p></div></div><nav class="journey-index" aria-label="${say('Journey stages','성장 여정 단계')}"><div class="container">${journeyStages.map((stage,i)=>`<a href="#journey/${stage.id}" data-journey-stage="${stage.id}"><span>0${i+1}</span> ${txt(projects.find(p=>p.id===stage.id).navLabel)}</a>`).join('')}</div></nav><div class="container journey-timeline">${journeyStages.map((stage,i)=>{const p=projects.find(p=>p.id===stage.id);return `<section class="journey-chapter" id="journey-${stage.id}" aria-labelledby="journey-title-${stage.id}"><div class="chapter-meta"><span class="chapter-number">0${i+1}</span><span class="eyebrow">${esc(p.period)}</span><h2 id="journey-title-${stage.id}">${txt(stage.stage)}</h2><a class="text-link" href="#project/${stage.id}">${txt(p.short)} ${arrow}</a></div><div class="chapter-content"><div class="chapter-lanes"><div><h3>${say('THE NEXT PROBLEM','다음으로 해결할 문제')}</h3><p>${txt(stage.problem)}</p></div><div><h3>${say('MY EXPANDING RESPONSIBILITY','넓어진 담당 범위')}</h3><p>${txt(stage.role)}</p></div></div><div class="chapter-result"><span>${stage.id==='master-data'?say('MEASURED RESULT','측정 성과'):['digital-twin','data-platform'].includes(stage.id)?say('DELIVERY SCOPE','적용 범위'):say('DELIVERED CHANGE','업무 변화')}</span><p>${txt(p.cardProof)}</p></div><div class="chapter-growth"><span>${say('ROLE DEVELOPMENT','역할의 확장')}</span><strong>${txt(stage.growth)}</strong></div><div class="chapter-bridge"><span aria-hidden="true">${i===journeyStages.length-1?'↗':'↓'}</span><p>${txt(stage.enabled)}</p></div></div></section>`;}).join('')}<aside class="parallel-work"><div><span class="eyebrow">${say('ALONGSIDE PRODUCT DELIVERY','서비스 개발과 함께')}</span><h2>${say('Shared engineering practices','팀이 함께 사용하는 개발 기준')}</h2><p>${say('Reusable API, design, testability and fallback guidance grew alongside these systems. Agent work extends existing workflows and data integrations using external models.','이 시스템들을 개발하면서 API·디자인·테스트 가능성·fallback 기준도 팀에서 재사용하도록 정리했습니다. 에이전트 업무는 외부 모델을 활용해 기존 워크플로와 데이터 연계를 확장하는 방향입니다.')}</p></div><a class="text-link" href="#project/engineering-practices">${say('Explore engineering practices','개발 방식 살펴보기')} ${arrow}</a></aside><div class="journey-end"><h2>${say('Explore the work behind this journey.','이 여정의 실제 과제를 확인하세요.')}</h2><div class="actions"><a class="button" href="#work">${say('Selected systems','대표 시스템')} ${arrow}</a><a class="button light" href="#experience">${say('More experience','추가 경험')} ${arrow}</a><a class="text-link" href="${esc(resumePdfUrl)}" target="_blank" rel="noopener">${say('Résumé (PDF)','이력서 (PDF)')} ${arrow}</a></div></div></div></article>`;
}
function caseConnections(p){
 const stage=journeyById[p.id];
 if(!stage)return `<aside class="case-journey-link"><span>${say('Shared practices developed alongside production systems.','운영 시스템 개발과 함께 발전시킨 팀 개발 방식입니다.')}</span><a class="text-link" href="#journey">${say('See the journey','성장 여정 보기')} ${arrow}</a></aside>`;
 const prior=journeyStages[stage.index-1],next=journeyStages[stage.index+1];
 return `<aside class="case-journey-link"><div><span class="eyebrow">${say('ROLE DEVELOPMENT','역할의 확장')}</span><p>${txt(stage.growth)}</p><div class="related-foundations">${prior?`<a href="#project/${prior.id}">${say('Foundation: ','출발 기반: ')}${txt(projects.find(c=>c.id===prior.id).navLabel)} ↗</a>`:''}${next?`<a href="#project/${next.id}">${say('Next extension: ','이어진 확장: ')}${txt(projects.find(c=>c.id===next.id).navLabel)} ↗</a>`:''}</div></div><a class="text-link" href="#journey/${p.id}">${say('See this stage in my journey','성장 여정에서 확인하기')} ${arrow}</a></aside>`;
}
function renderDeliverySections(p){return `<section class="delivery-section" id="case-delivery" aria-labelledby="delivery-title"><div class="delivery-heading"><span class="eyebrow">${say('MY CONTRIBUTION','직접 담당한 부분')}</span><h2 id="delivery-title">${say('What I delivered.','직접 수행한 업무와 구현.')}</h2></div><div class="delivery-cards">${p.deliverySections.map(section=>`<div><h3>${txt(section.title)}</h3><p>${txt(section.text)}</p></div>`).join('')}</div></section>`;}

function card(p,index){return `<a href="#project/${p.id}" class="project-card" aria-label="${say('Read case study: ','사례 보기: ')}${txt(p.short)}"><figure class="card-art"><img src="${new URL('concept-'+p.id+'.svg',assetBase).href}" alt="${say('Concept illustration for ','프로젝트 컨셉 이미지: ')}${txt(p.short)}" width="640" height="420" loading="lazy"><figcaption>${say('CONCEPT ILLUSTRATION','컨셉 일러스트')}</figcaption></figure><div class="card-content"><div class="card-meta"><span class="eyebrow">${txt(p.category)}</span><span class="project-number">${p.number} /</span></div><h3>${txt(p.short)}</h3><p class="card-roles">${p.roles.slice(0,3).map(txt).join(' · ')}</p><div class="card-proof">${txt(p.cardProof)}</div><div class="card-tags">${p.stack.slice(0,3).map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div><div class="card-link"><span>${say('Explore the case','프로젝트 자세히 보기')}</span>${arrow}</div></div></a>`;}
function philosophySection(){
 const skills=[['01','Requirements & boundaries','요구사항 · 경계','Define inputs, business rules and acceptance criteria before generating code.','코드 생성 전에 업무 흐름·입력·업무 규칙·완료 기준을 명확히 합니다.'],['02','API & UI consistency','API · UI 일관성','Reuse API contracts, validation rules and interface design standards.','API 명세·검수·응답 방식·UI 디자인 기준을 Skill 문서로 재사용합니다.'],['03','Testability & review','테스트 가능성 · 리뷰','Make dependencies and error states explicit for testing and review.','오류 상태와 의존 관계를 명시해 생성한 코드를 검증하고 유지보수할 수 있게 합니다.'],['04','Fallback & operations','실패 대응 · 운영','Define failure and recovery behaviour, with engineering review of operational decisions.','실패 시 동작과 복구 경로를 정의하고, 운영 판단은 엔지니어가 검토합니다.']];
 return `<section class="philosophy container" id="philosophy" aria-labelledby="philosophy-title"><div class="section-heading"><div><div class="eyebrow">03 / AI PHILOSOPHY</div><h2 id="philosophy-title">${say('Faster code. Deliberate engineering.','빠른 코딩에, 체계적인 설계를 더합니다.')}</h2></div><p>${say('I use reusable skills to guide AI-assisted development: clear requirements, consistent interfaces, testable code and defined recovery paths.','요구사항·API·UI·테스트·실패 대응 기준을 재사용 가능한 Skill로 작성해 AI 활용 개발에 적용합니다.')}</p></div><div class="skill-grid">${skills.map(([n,en,ko,den,dko])=>`<article><span class="eyebrow">SKILL / ${n}</span><h3>${say(en,ko)}</h3><p>${say(den,dko)}</p></article>`).join('')}</div><details class="skill-example-detail"><summary>${say('Example: reliable document ingestion','적용 예시: 신뢰할 수 있는 문서 수집')} <span aria-hidden="true">＋</span></summary><div class="skill-example"><div><span class="eyebrow">${say('AN EXAMPLE OF THE STANDARD','기준을 적용하는 예시')}</span><h3>${say('A repeated submission must stay one submission.','같은 제출물은 반복 요청에도 하나로 처리되어야 합니다.')}</h3><p>${say('For document ingestion, this means defining identity and validation first, implementing duplicate detection and retries, then reviewing failure and recovery behaviour.','문서 수집에서는 식별 기준과 검수 규칙을 먼저 정하고, 중복 감지·재시도를 구현한 뒤 실패와 복구 동작을 검토합니다.')}</p></div><dl><div><dt>${say('Contract','명세')}</dt><dd>${say('Identity · validation · acceptance','식별 기준 · 검수 · 완료 조건')}</dd></div><div><dt>${say('Implementation','구현')}</dt><dd>${say('Idempotency · retries · error states','멱등성 · 재시도 · 오류 상태')}</dd></div><div><dt>${say('Review','검토')}</dt><dd>${say('Duplicate · failed · recovered','중복 · 실패 · 복구 시나리오')}</dd></div></dl></div></details><div class="philosophy-foot"><p>${say('Agent work remains at prototype stage.','에이전트 업무는 프로토타입 단계입니다.')}</p><a class="text-link" href="#project/engineering-practices">${say('See the engineering practices','개발 방식 사례 보기')} ${arrow}</a></div></section>`;
}
function careerProgression(){
 const rows=[['2019 — 2020','Facilities engineer','설비 엔지니어','Equipment reliability, maintenance analysis and firsthand operational context.','설비 신뢰성·보전 분석·현장 업무 이해'],['2020 — 2022','Data & systems analyst','데이터 · 시스템 분석가','Data standards, lifecycle workflows, Python/SQL validation and system integrations.','데이터 표준·생애주기 업무 설계·Python/SQL 검수·시스템 연계'],['2023 — Present','Developer & business automation','개발자 · 비즈니스 자동화','Full-stack applications, AWS/on-premises delivery and production operations.','풀스택 애플리케이션·AWS/사내 배포·운영 자동화']];
 return `<div class="career"><div class="career-head"><span>Samsung Electronics</span><span class="eyebrow">2019 — ${say('PRESENT','현재')}</span></div><div class="career-progression">${rows.map(([date,en,ko,den,dko],i)=>`<div class="career-row"><span class="career-step">0${i+1}</span><div><span class="career-date">${date==='2023 — Present'?say(date,'2023 — 현재'):date}</span><h3 class="career-name">${say(en,ko)}</h3><p class="career-desc">${say(den,dko)}</p></div></div>`).join('')}</div><p class="career-note">${say('Role focus shown above. Formal titles: Facilities Engineer (2019–2020); Systems Engineer (2020–present).','위 흐름은 주요 역할의 변화입니다. 공식 직함: 설비 엔지니어(2019–2020), 시스템 엔지니어(2020–현재).')}</p></div>`;
}
function confidentiality(compact=false){return compact?`<p class="confidential-note"><strong>${say('CASE STUDY & CONFIDENTIALITY','사례 공개 범위 · 보안 안내')}</strong>${say('Company code, internal screens and production data are confidential. Diagrams show high-level workflows.','회사 코드·내부 화면·운영 데이터는 공개하지 않습니다. 도식은 상위 업무 흐름을 설명합니다.')}</p>`:`<details class="disclosure" id="disclosure" open><summary>${say('About these case studies & confidentiality','사례 공개 범위 · 보안 안내')} <span aria-hidden="true">＋</span></summary><p>${say('These case studies explain my role, workflows and engineering decisions. Company code, internal screens, production data and detailed infrastructure remain confidential. Illustrations are conceptual.','담당 역할·업무 흐름·설계 판단을 설명합니다. 회사 코드·내부 화면·운영 데이터·상세 인프라는 기밀로 공개하지 않으며, 이미지는 컨셉 일러스트입니다.')}</p></details>`;}
